@startuml

class Resident {
  + name : string
  + streetAddress : string
  + phoneNumber : string
  + email : string
}

class PickupRequest {
  + streetAddress : string
  + description : string
  + pickupTime : time
}

class Vehicle {
  + storageSpace : float
}

class Route {
  + date : date
}

class VolunteerDriver {
  + availableDays : string[]
}

class Article {
  + description : string
  + dimensions : string
  + weight : float
}

class Category {
  + name : string
}

class DistributionCenter {
  + name : string
}

class H2SEmployee {
  + name : string
}

class Client {
  + homeAddress : string
}

class FoodBank {
  + name : string
}

class FoodItem {
  + description : string
}

class Delivery {
  + date : date
}

Resident "1" -- "*" PickupRequest : makes
PickupRequest "1" -- "1" Vehicle : assigned to
PickupRequest "1" -- "1" VolunteerDriver : driven by
PickupRequest "1" -- "1" Route : part of
Route "1" -- "1" Vehicle : for
VolunteerDriver "1" -- "*" Route : operates
PickupRequest "1" -- "0..1" Article : results in
Article "*" -- "1" Category : belongs to
Article "*" -- "1" DistributionCenter : delivered to
Article "1" -- "1" H2SEmployee : inspected by
Article "1" -- "1" DistributionCenter : stored at
Article "0..1" -- "1" RFID : has
RFID {}

H2SEmployee "1" -- "*" Article : examines
H2SEmployee "1" -- "*" Delivery : arranges
Client "1" -- "*" Delivery : receives
Delivery "1" -- "1" VolunteerDriver : performed by
Delivery "1" -- "1" Article : contains
Client "1" -- "0..1" DistributionCenter : served by
FoodItem "*" -- "1" FoodBank : delivered to

@enduml

